//get the PDF byte array from Param page
byte[] byteArray=(byte[])tools.getParameterPage().getParameterValue("PDFDocument");

//encode the byte array into Base64.

try
{
	strFileData = Base64Util.encodeToString(byteArray);
}
catch (Exception e)
{
	throw new PRRuntimeException("Can't attach the file to the Work Object");
}

ClipboardPage workPage = tools.findPageByHandle(tools.getParamValue("InsHandle"));
//BUG-178463 Fetch the Handle and use the step Page to attach the attachment
if(pega_rules_page.getStepPageHandle(tools).equals(tools.getParamValue("InsHandle"))){
      tools.putParamValue("pyPDFAttachWorkPage", myStepPage.getName());
      bRemoveWhenDone = false;
}
else if (workPage != null) {
      tools.putParamValue("pyPDFAttachWorkPage", workPage.getName());
      bRemoveWhenDone = false;
} else {
      tools.createPage("Work-","pyPDFAttachWorkPage");
      tools.putParamValue("pyPDFAttachWorkPage", "pyPDFAttachWorkPage");
      bRemoveWhenDone = true;
}
